class Solution:
    def generateParenthesis(self, n: int) -> list[str]:

        # Initialize the result
        res = []

        # Recursively go through all possible combinations
        def add(open, close, partialRes):

            nonlocal res

            # If we have added opening and closing parentheses n times, we reaches a solution
            if open == close == n:
                res.append("".join(partialRes))
                return

            # Add a closing parenthesis to the partial result if we have at least 1 opening parenthesis
            if close < open:
                add(open, close + 1, partialRes + [")"])

            # Add an opening parenthesis to the partial result if we haven't added n parenthesis yet
            if open < n:
                add(open + 1, close, partialRes + ["("])

        add(0, 0, [])

        return res

class Solution:
    def generateParenthesis(self, n: int) -> list[str]:
        def generateParenthesisRecu(left, right, curr, result):
            if left == 0 and right == 0:
                result.append("".join(curr))
            if left > 0:
                curr.append('(')
                generateParenthesisRecu(left-1, right, curr, result)
                curr.pop()
            if left < right:
                curr.append(')')
                generateParenthesisRecu(left, right-1, curr, result)
                curr.pop()

        result = []
        generateParenthesisRecu(n, n, [], result)
        return result

class Solution:
    def generateParenthesis(self, n: int) -> list[str]:
        result, curr = [], []
        stk = [(1, (n, n))]
        while stk:
            step, args = stk.pop()
            if step == 1:
                left, right = args
                if left == 0 and right == 0:
                    result.append("".join(curr))
                if left < right:
                    stk.append((3, tuple()))
                    stk.append((1, (left, right-1)))
                    stk.append((2, (')')))
                if left > 0:
                    stk.append((3, tuple()))
                    stk.append((1, (left-1, right)))
                    stk.append((2, ('(')))
            elif step == 2:
                curr.append(args[0])
            elif step == 3:
                curr.pop()
        return result

